// hugo/static/js/featured-rail.js
// Live-refresh the Tutorial Navigator "Featured" rail from /build/featured.
// Fail-silent: keep SSR content on any error / non-ok / empty. Mirrors popular-rail.js.
(async function upgradeFeaturedRail() {
  const rail = document.getElementById('featured-rail');
  if (!rail) return;
  const hrefBase = rail.dataset.hrefBase || '/tutorials';

  // Build the navigator content URL for a featured item. Matches the page URLs
  // generated by scripts/fetch-tutorials.ts (buildBrowseCards):
  //   tutorial -> <base>/<slug>   mission -> <base>/mission-<slug>   group -> <base>/group-<slug>
  function hrefFor(f) {
    const slug = encodeURIComponent(f.slug);
    if (f.type === 'mission') return `${hrefBase}/mission-${slug}`;
    if (f.type === 'group') return `${hrefBase}/group-${slug}`;
    return `${hrefBase}/${slug}`; // tutorial
  }

  try {
    const res = await fetch('/build/featured', { credentials: 'omit' });
    if (!res.ok) return;                       // 304 / 5xx -> keep SSR
    const data = await res.json();
    const featured = Array.isArray(data && data.featured) ? data.featured : [];
    if (featured.length === 0) return;         // empty -> keep fallback SSR

    const cards = featured.slice(0, 6).map((f) => {
      const a = document.createElement('a');
      a.className = 'nav-card';
      a.setAttribute('data-vt-card', 'navigator');
      a.href = hrefFor(f);
      // Build structure WITHOUT innerHTML for untrusted fields (title/description).
      const typeDiv = document.createElement('div');
      typeDiv.className = `nav-card__type nav-card__type--${f.type}`;
      typeDiv.textContent = (f.type || '').toUpperCase();
      const h3 = document.createElement('h3');
      h3.className = 'nav-card__title';
      h3.textContent = f.title || '';
      const p = document.createElement('p');
      p.className = 'nav-card__desc';
      p.textContent = (f.description || '').slice(0, 160);
      a.append(typeDiv, h3, p);
      return a;
    });
    rail.replaceChildren(...cards);
    rail.dataset.source = 'curated-live';
  } catch (err) {
    if (window.console) console.debug('[featured-rail] upgrade failed:', err);
  }
})();
